var scene = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
var sb = new System.Text.StringBuilder();
sb.Append("scene=" + scene.name + " rootCount=" + scene.rootCount + "
");
foreach (var r in scene.GetRootGameObjects())
{
    sb.Append("ROOT: ").Append(r.name).Append(" active=").Append(r.activeSelf).Append(" children=").Append(r.transform.childCount).Append("
");
    var c0 = r.transform.childCount;
    for (int i = 0; i < c0; i++)
    {
        var ch = r.transform.GetChild(i);
        sb.Append("   - ").Append(ch.name).Append(" active=").Append(ch.gameObject.activeSelf).Append("
");
    }
}
var s = scene.GetRootGameObjects();
foreach (var r in s)
{
    var comps = r.GetComponents<Component>();
    var names = new System.Text.StringBuilder();
    foreach (var c in comps) { if (c != null) names.Append(c.GetType().Name).Append(","); }
    sb.Append("COMPS ").Append(r.name).Append(": ").Append(names).Append("
");
}
return sb.ToString();
